import bpy,json,re
from mathutils import Vector
from pathlib import Path
print('NAMESPACE', 'shipyard_craft' in bpy.app.driver_namespace)
report={}
for which in ['A','B']:
 c=bpy.data.collections['Shipyard_'+which+'_Craft'];groups={}
 for o in c.objects:
  key=re.sub(r'\.\d+$','',o.name)
  if key not in groups:
   coords=[o.matrix_world@Vector(v) for v in o.bound_box]
   groups[key]={'count':0,'lo':[round(min(p[i] for p in coords),3) for i in range(3)],'hi':[round(max(p[i] for p in coords),3) for i in range(3)]}
  groups[key]['count']+=1
 report[which]=groups
p=Path(bpy.data.filepath).parent.parent/'captures'/'shipyard_combined_20261110'/'component_audit.json';p.write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf8')
print('COMPONENT_AUDIT_SAVED',str(p))
